INSERT INTO public."companyProfile" (id, company_id, profile, "generatedAt", competitors, tags) VALUES (1, 1, 'Founded in 1975 and headquartered in Redmond, Microsoft is a global technology leader with an approximate revenue of $93.58 billion. The company is best known for its key product, Microsoft Windows, and manages a vast ecosystem including subsidiaries like Xbox Game Studios.', '2026-10-26 17:40:53.094', '["Apple Inc.","IBM","Oracle Corporation"]', '["Technology","Software","Operating Systems","Consumer Electronics"]'), (2, 2, 'Founded in 1998 and headquartered in Mountain View, Google is a global leader in the internet industry, best known for its dominant search engine. As a subsidiary of Alphabet Inc., the company employs approximately 48,000 people and operates key products including Google Search and AdMob.', '2026-10-26 17:41:19.241', '["Bing","Yahoo!","DuckDuckGo"]', '["Internet","Search Engine","Technology","Advertising","Digital Services"]'), (3, 3, 'Founded in 2009 and headquartered in San Francisco, Cloudflare is a leading provider of reverse proxy and cybersecurity solutions for the web. The company generates approximately $656.43 million in revenue while serving over 1,000 employees.', '2026-10-26 17:21:02.997', '["Akamai Technologies","AWS (Amazon Web Services)","Fastly"]', '["Information Technology","Cybersecurity","Web Services","Networking","Cloud Computing"]'), (4, 4, 'Founded in 1993 and headquartered in Santa Clara, United States, Nvidia is a semiconductor industry leader known for its innovative graphics processing units (GPUs). With an approximate revenue of $4.10 billion, the company continues to drive advancements in parallel computing and AI technologies.', '2026-10-26 17:41:56.073', '["Advanced Micro Devices (AMD)","Intel","Qualcomm"]', '["Semiconductors","Hardware","Graphics Processing","Technology","AI Infrastructure"]'), (5, 5, 'Founded in 1969 and headquartered in Sunnyvale, AMD is a leading innovator in the electrical industry, specializing in high-performance computer hardware. With a market capitalization of $101.84B and annual revenue of approximately $5.33B, the company plays a pivotal role in the semiconductor landscape under the leadership of CEO Lisa Su.', '2026-10-26 17:42:15.253', '["NVIDIA","Intel","Qualcomm"]', '["Electrical","Semiconductors","Hardware","Technology","Computer Hardware"]'), (6, 6, 'Founded in 1994 and headquartered in Seattle, Amazon is a global retail giant that has expanded from e-commerce into hardware with key products like the Amazon Echo. With an approximate annual revenue of $14.84 billion, the company remains a dominant force in the technology and consumer goods sectors.', '2026-10-26 17:42:32.567', '["Walmart","eBay","Alibaba"]', '["Retail","E-commerce","Technology","Consumer Electronics","Cloud Computing"]'), (7, 7, 'Founded in 1938 and headquartered in South Korea, Samsung is a global conglomerate renowned for its leading position in consumer electronics. With a workforce of approximately 590,000 employees, the company generates substantial revenue of $208.50 billion, solidifying its status as a dominant force in the technology sector.', '2026-10-26 17:42:53.037', '["Apple Inc.","LG Electronics","Sony Corporation"]', '["Electronics","Conglomerate","Consumer Technology","Semiconductors","South Korea"]'), (8, 8, 'Founded in 1976 and headquartered in Cupertino, Apple is a global leader in consumer electronics and software, widely recognized for the Apple TV and its integrated ecosystem. The company commands a massive market presence with an approximate revenue of $233.72 billion.', '2026-10-26 17:43:09.77', '["Samsung Electronics","Microsoft","Google"]', '["Technology","Consumer Electronics","Software","Hardware","Media"]'), (9, 9, 'Founded in Beijing in 2010, Mi is a leading consumer electronics company known for its wide range of computer hardware and smart devices. With a net income of $13.48B and a substantial workforce of 17,000 employees, the company has established itself as a major player in the global tech market.', '2026-10-26 17:43:42.505', '["Apple","Samsung","Huawei"]', '["Consumer Electronics","Smartphones","IoT","Hardware","Smart Home"]'), (10, 10, 'Founded in 1987 and headquartered in Hsinchu Science Park, Taiwan, TSMC is a global leader in the semiconductor industry, specializing in the fabrication of central processing units. With an approximate revenue of $1.34 trillion, the company stands as a pivotal force in the tech supply chain and is listed on the New York Stock Exchange.', '2026-10-26 17:44:21.403', '["Samsung Electronics","Intel","GlobalFoundries"]', '["Semiconductor","Technology","Hardware","Manufacturing","CPUs"]'), (14, 11, 'Founded in 2015 and headquartered in San Francisco, this leading artificial intelligence company is renowned for its groundbreaking product, DALL-E. With a workforce of approximately 5,000 employees, the organization generates an estimated revenue of $44,000.', '2026-10-26 19:17:34.196', '["Anthropic","Stability AI","Midjourney"]', '["Artificial Intelligence","Generative AI","Software","Image Generation","Technology"]'), (16, 14, 'Founded in 1987 and headquartered in Shenzhen, Huawei is a global telecommunications giant with an approximate revenue of $521.57 billion. The company is best known for its broadband Internet access solutions and operates through key subsidiaries like HiSilicon.', '2026-10-26 19:17:05.7', '["Ericsson","Nokia","ZTE"]', '["Telecommunications","Networking Equipment","5G","Consumer Electronics","China"]'), (17, 22, 'Founded in 1968 and headquartered in Santa Clara, United States, Intel is a semiconductor industry leader generating approximately $55.35 billion in revenue. The company, listed on Nasdaq, is a global powerhouse in computing technology with a market capitalization of $200 billion.', '2026-10-26 19:17:24.222', '["AMD","NVIDIA","Qualcomm"]', '["Semiconductors","Hardware","Technology","Microprocessors","Nasdaq"]');